const cfg=window.PORTFOLIO_CONFIG||{};const f=document.querySelector('#ddh-file'),run=document.querySelector('#ddh-run'),out=document.querySelector('#ddh-output');if(f&&run&&out&&cfg.ddh?.baseUrl){fetch(`${cfg.ddh.baseUrl}/health`).then(r=>r.json()).then(h=>{out.innerHTML=`<span class="output-mark">●</span><p>Local model service ready.</p><small>${h.model} loaded · research prototype</small>`;run.disabled=false;run.classList.remove('disabled');run.textContent='Run local model →'}).catch(()=>{out.textContent='Local model service unavailable.'});run.addEventListener('click',async()=>{if(!f.files[0]){out.textContent='Choose an image first.';return}let d=new FormData();d.append('image',f.files[0]);run.disabled=true;run.textContent='Running inference…';try{let r=await fetch(`${cfg.ddh.baseUrl}/analyze`,{method:'POST',body:d}),j=await r.json();if(!r.ok)throw Error(j.detail||'Inference failed');out.innerHTML=`<img src="${j.overlay}" alt="Model overlay"><p>${j.landmarks_detected} landmark groups detected.</p><small>best11.pt · ${j.inference_ms} ms inference</small>`}catch(e){out.textContent=e.message}finally{run.disabled=false;run.textContent='Run local model →'}})}
